<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher,tick} from 'svelte';
 import {CompanyChannelsClient,channelDraft,type ChannelDraft,type ChannelSettings} from './channels-client';
 export let companyId:string;
 export let actorId:string;
 export let people:{id:string;name:string;kind?:string}[]=[];
 export let bots:{id:string;name:string}[]=[];
 export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher();
 let client:CompanyChannelsClient|null=null,boundSignal:AbortSignal|undefined,ready=false,scope='',authorized=false,denied=false,loading=true,loadingMore=false,busy=false,error='',notice='';
 let draft:ChannelDraft;
 let channels:ChannelSettings[]=[],hasMore=false,next='',filter='',editor=false,loadingEditor=false,editorEpoch=0,current:ChannelSettings|null=null,name='',description='',visibility:'public'|'private'='public',memberIds:string[]=[],agentIds:string[]=[],baseline='',conflict=false,uncertainCreate=false,uncertainUpdate=false,editorTitle:HTMLElement;
 $: key=JSON.stringify([companyId,actorId]);
 $: if(ready&&(key!==scope||boundSignal!==accessSignal)){scope=key;bindAccess();void load();}
 $: humanOptions=[...new Map(people.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&!['bot','agent'].includes(p.kind||'')).map(p=>[p.id,p])).values()];
 $: botOptions=[...new Map(bots.filter(b=>b&&typeof b.id==='string'&&typeof b.name==='string').map(b=>[b.id,b])).values()];
 $: shown=channels.filter(c=>(c.name+' '+c.description).toLocaleLowerCase().includes(filter.toLocaleLowerCase()));
 $: draft={name,description,visibility,memberIds:visibility==='private'?memberIds:[],agentIds};
 $: dirty=editor&&(current?JSON.stringify(channelDraft(draft))!==baseline:!!(name.trim()||description||agentIds.length||visibility==='private'));
 $: missingPeople=visibility==='private'?memberIds.filter(id=>!humanOptions.some(p=>p.id===id)&&!(id===actorId&&!current)):[];
 $: missingBots=agentIds.filter(id=>!botOptions.some(b=>b.id===id));
 $: invalid=!name.trim()||name.trim().length>100||description.length>2000||(visibility==='private'&&current!==null&&!memberIds.length)||missingPeople.length>0||missingBots.length>0;
 function bindAccess(){boundSignal?.removeEventListener('abort',parentRevoked);boundSignal=accessSignal;boundSignal?.addEventListener('abort',parentRevoked,{once:true});}
 function clearEditor(){editorEpoch++;editor=false;loadingEditor=false;current=null;name='';description='';visibility='public';memberIds=[];agentIds=[];baseline='';conflict=false;uncertainCreate=false;uncertainUpdate=false;}
 function revoke(status=403){client?.forgetSession();client=null;channels=[];authorized=false;loading=false;loadingMore=false;busy=false;hasMore=false;next='';filter='';notice='';clearEditor();error=status===401?'Your session changed. Reopen the company workspace.':'Company access changed. Reopen the company workspace.';dispatch('accesschanged',{status});}
 function parentRevoked(){revoke();}
 function failure(e:any){if(e?.status===401||(e?.status===403&&(!e.managementDenied||authorized))){revoke(e.status);return;}if(e.managementDenied){denied=true;authorized=false;error=e.message;return;}error=e?.message||'Channel settings are unavailable.';}
 async function load(){if(!companyId||!actorId){loading=false;return;}if(accessSignal?.aborted){revoke();return;}client?.close();const active=client=new CompanyChannelsClient(companyId,actorId,()=>localStorage.token||'');channels=[];authorized=false;denied=false;loading=true;hasMore=false;next='';error='';notice='';clearEditor();try{const page=await active.list();if(active!==client)return;channels=page.channels;hasMore=page.hasMore;next=page.next;authorized=true;const pending=active.resumeCreate();if(pending){editor=true;({name,description,visibility,memberIds,agentIds}=pending.draft);uncertainCreate=true;await focusEditor();}}catch(e){if(active===client)failure(e);}finally{if(active===client)loading=false;}}
 async function more(){if(!client||loadingMore||!hasMore)return;const active=client;loadingMore=true;error='';try{const page=await active.list(next);if(active!==client)return;channels=[...new Map([...channels,...page.channels].map(c=>[c.id,c])).values()];hasMore=page.hasMore;next=page.next;}catch(e){if(active===client)failure(e);}finally{if(active===client)loadingMore=false;}}
 async function focusEditor(){await tick();editorTitle?.focus();editorTitle?.scrollIntoView({block:'nearest',behavior:'smooth'});}
 async function create(){if(!authorized||busy||dirty||uncertainCreate)return;clearEditor();editor=true;memberIds=[actorId];error='';notice='';await focusEditor();}
 function fill(value:ChannelSettings){channels=channels.map(c=>c.id===value.id?value:c);current=value;name=value.name;description=value.description;visibility=value.visibility;memberIds=value.visibility==='private'?[...value.memberIds]:[actorId];agentIds=[...value.agentIds];baseline=JSON.stringify(channelDraft(value));conflict=false;uncertainUpdate=false;uncertainCreate=false;}
 async function edit(value:ChannelSettings){if(!client||busy||loadingEditor||dirty||uncertainCreate)return;const active=client,epoch=++editorEpoch;editor=true;loadingEditor=true;error='';notice='';try{const fresh=await active.read(value.id);if(active!==client||epoch!==editorEpoch)return;fill(fresh);await focusEditor();}catch(e){if(active===client&&epoch===editorEpoch)failure(e);}finally{if(active===client&&epoch===editorEpoch)loadingEditor=false;}}
 async function reloadEditor(){if(!current||!client||busy)return;const active=client,epoch=++editorEpoch;loadingEditor=true;error='';try{const fresh=await active.read(current.id);if(active!==client||epoch!==editorEpoch)return;fill(fresh);notice='Latest channel settings loaded. Your previous draft was discarded.';}catch(e){if(active===client&&epoch===editorEpoch)failure(e);}finally{if(active===client&&epoch===editorEpoch)loadingEditor=false;}}
 async function save(){if(!client||busy||invalid||conflict||uncertainUpdate||loadingEditor||(!dirty&&current))return;const active=client,epoch=editorEpoch;busy=true;error='';notice='';try{const result=current?await active.update(current.id,current.revision,draft):await active.create(draft);if(active!==client||epoch!==editorEpoch)return;channels=[...new Map([...channels,result].map(c=>[c.id,c])).values()].sort((a,b)=>a.id.localeCompare(b.id));fill(result);notice=(result.cancelledRunIds?.length?`Channel saved. ${result.cancelledRunIds.length} active agent run(s) stopped while applying the configuration.`:'Channel saved.');dispatch('changed',{companyId,channel:result,cancelledRunIds:result.cancelledRunIds||[]});}catch(e){if(active!==client||epoch!==editorEpoch)return;const status=(e as any).status;if(status===409&&current)conflict=true;else if(current&&(!status||status>=500))uncertainUpdate=true;uncertainCreate=!!active.resumeCreate();failure(e);}finally{if(active===client)busy=false;}}
 async function archiveChannel(value:ChannelSettings){if(!client||busy||dirty||!window.confirm('Archive '+value.name+'? It will no longer appear in company conversations.'))return;const active=client;busy=true;error='';try{await active.archive(value.id,value.revision);if(active!==client)return;channels=channels.filter(c=>c.id!==value.id);if(current?.id===value.id)clearEditor();notice='Channel archived.';dispatch('changed',{companyId,channelId:value.id,archived:true});}catch(e){if(active===client)failure(e);}finally{if(active===client)busy=false;}}
 function openRoom(value:ChannelSettings){if(value.canOpen&&!busy&&!dirty&&!uncertainCreate&&!uncertainUpdate)dispatch('open',{roomId:value.id});}
 function session(e:StorageEvent){if(e.key==='token'||e.key===null)revoke(401);}
 onMount(()=>{ready=true;window.addEventListener('storage',session);return()=>window.removeEventListener('storage',session);});onDestroy(()=>{client?.close();boundSignal?.removeEventListener('abort',parentRevoked);});
</script>

<section class="company-channels" aria-label="Company channels" aria-busy={loading||busy}>
 <header><div><p class="eyebrow">COMPANY MANAGEMENT</p><h1>Channels</h1><p class="intro">Create shared spaces and choose who belongs in each conversation.</p></div>{#if authorized}<button class="primary" disabled={busy||loadingEditor||dirty||uncertainCreate} on:click={create}><svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M10 4v12M4 10h12" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>New channel</button>{/if}</header>
 {#if error}<div class="alert" role="alert">{error}{#if conflict} Your draft is kept. Discard it and reload the latest configuration before saving again.{:else if uncertainUpdate} This update is unconfirmed. Reload before making another change.{:else if uncertainCreate} Creation is unconfirmed. Retry the same configuration to retrieve the original channel.{/if}</div>{/if}
 {#if notice}<div class="notice" role="status">{notice}</div>{/if}
 {#if loading}<div class="empty" role="status">Checking company access and loading channels…</div>{:else if !authorized}<div class="empty"><div class="empty-icon">#</div><h2>{denied?'Administrator access required':'Channel management unavailable'}</h2><p>{denied?'Company owners and administrators manage channel settings.':'Reload to check the native company service. No local channel changes have been made.'}</p><button class="secondary" on:click={load}>Reload</button></div>
 {:else}<div class="layout" class:editing={editor}>
 <div class="channel-list"><div class="list-toolbar"><label class="search"><svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5" stroke="currentColor" stroke-width="1.4"/><path d="m12.3 12.3 4 4" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg><input aria-label="Filter channels" bind:value={filter} placeholder="Find a channel"/></label><span>{channels.length} {hasMore?'loaded':'channel'+(channels.length===1?'':'s')}</span><button class="text-button" disabled={busy||dirty||uncertainCreate} on:click={load}>Refresh</button></div>
 <div class="table-scroll"><table><thead><tr><th>Channel</th><th>Visibility</th><th class="counts">Members</th><th class="row-actions"><span class="sr-only">Actions</span></th></tr></thead><tbody>{#each shown as channel(channel.id)}<tr class:selected={current?.id===channel.id}><td><div class="channel-name"><span class="hash">#</span><div><strong>{channel.name}</strong><p>{channel.description||'No description'}</p></div></div></td><td><span class="visibility" class:private={channel.visibility==='private'}>{#if channel.visibility==='private'}<svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><rect x="4" y="7" width="8" height="6" rx="1.5" stroke="currentColor"/><path d="M5.5 7V5a2.5 2.5 0 0 1 5 0v2" stroke="currentColor"/></svg>Private{:else}Company-wide{/if}</span></td><td class="counts"><span>{channel.memberIds.length} people</span><small>{channel.agentIds.length} {channel.agentIds.length===1?'agent':'agents'}</small></td><td class="row-actions"><button class="secondary compact" disabled={busy||loadingEditor||dirty||uncertainCreate} on:click={()=>edit(channel)} aria-label={'Manage '+channel.name}>Manage</button> <button class="secondary compact" disabled={busy||loadingEditor||dirty||uncertainCreate||uncertainUpdate} on:click={()=>archiveChannel(channel)} aria-label={'Archive '+channel.name}>Archive</button><button class="text-button open" disabled={!channel.canOpen||busy||dirty||uncertainCreate||uncertainUpdate} on:click={()=>openRoom(channel)} title={channel.canOpen?'Open conversation':'Private history is not shared with you'}>Open <span aria-hidden="true">↗</span></button></td></tr>{:else}<tr><td colspan="4" class="table-empty">{filter?'No loaded channels match your search.':'No channels yet. Create a shared space for your team.'}</td></tr>{/each}</tbody></table></div>
 {#if hasMore}<div class="paging"><span>More channels are available{filter?' outside this filtered page':''}.</span><button class="secondary compact" disabled={loadingMore||busy} on:click={more}>{loadingMore?'Loading…':'Load more'}</button></div>{/if}</div>
 {#if editor}<aside class="editor"><div class="editor-heading"><div><p class="eyebrow">{current?'CHANNEL SETTINGS':'NEW CHANNEL'}</p><h2 tabindex="-1" bind:this={editorTitle}>{current?'Manage channel':'Create a channel'}</h2></div><button class="icon-button" disabled={busy||uncertainCreate} on:click={clearEditor} aria-label={dirty?'Discard draft and close editor':'Close channel editor'}>×</button></div>
 {#if loadingEditor}<p class="editor-loading" role="status">Loading current configuration…</p>{:else}<form on:submit|preventDefault={save}><label for="company-channel-name">Channel name</label><div class="name-field"><span>#</span><input id="company-channel-name" bind:value={name} maxlength="100" required disabled={busy||uncertainCreate}/></div><label for="company-channel-description">Description <span>Optional</span></label><textarea id="company-channel-description" bind:value={description} maxlength="2000" rows="3" disabled={busy||uncertainCreate} placeholder="What is this space for?"/>
 <fieldset class="visibility-choices" disabled={busy||uncertainCreate}><legend>Visibility</legend><label class:chosen={visibility==='public'}><input type="radio" name="channel-visibility" value="public" bind:group={visibility}/><span><strong>Company-wide</strong><small>Every current company member can open this channel.</small></span></label><label class:chosen={visibility==='private'}><input type="radio" name="channel-visibility" value="private" bind:group={visibility}/><span><strong>Private</strong><small>Only selected people can read its conversation history.</small></span></label></fieldset>
 {#if visibility==='public'}<div class="info">Company-wide channels include all current company members. A selected subset cannot restrict access.</div>{:else}<fieldset class="member-picker" disabled={busy||uncertainCreate}><legend>People <span>{memberIds.length} selected</span></legend>{#each humanOptions as person(person.id)}<label><input type="checkbox" value={person.id} bind:group={memberIds} disabled={!current&&person.id===actorId}/><span class="initial">{person.name.slice(0,1).toUpperCase()}</span><span>{person.name}{#if person.id===actorId}<small>You{!current?' · creator':''}</small>{/if}</span></label>{:else}<p class="muted">No people are available in the current directory.</p>{/each}</fieldset>{#if !current}<p class="hint">You are included as the creator of a new private channel.</p>{/if}{/if}
 <fieldset class="member-picker agents" disabled={busy||uncertainCreate}><legend>Agents <span>{agentIds.length} selected</span></legend>{#each botOptions as bot(bot.id)}<label><input type="checkbox" value={bot.id} bind:group={agentIds}/><span class="initial agent">{bot.name.slice(0,1).toUpperCase()}</span><span>{bot.name}<small>Company agent</small></span></label>{:else}<p class="muted">No agents are available in the current directory.</p>{/each}</fieldset><p class="hint">Adding an agent does not grant permissions or start a run.</p>
 {#if missingPeople.length||missingBots.length}<div class="alert small" role="alert">Some selected members are missing from the current directory. Refresh the company workspace before saving.</div>{/if}
 {#if current&&!current.canOpen}<div class="info restricted">You can manage this channel, but its private history is not shared with you.</div>{/if}
 {#if current}<p class="hint safety">Saving advances revision {current.revision} and stops active agent runs in this channel while applying the configuration.</p>{/if}
 <footer>{#if conflict||uncertainUpdate}<button type="button" class="secondary" disabled={busy} on:click={reloadEditor}>Discard draft & reload latest</button>{:else}<button type="button" class="secondary" disabled={busy||uncertainCreate} on:click={clearEditor}>{dirty?'Discard draft':'Close'}</button>{/if}<button class="primary" disabled={busy||invalid||conflict||uncertainUpdate||(!dirty&&!!current)}>{busy?'Saving…':uncertainCreate?'Retry original creation':current?'Save changes':'Create channel'}</button></footer>
 </form>{/if}</aside>{/if}
 </div>{/if}
</section>

<style>
 @font-face{font-family:'Enterprise Mona Sans';src:url('/assets/fonts/Mona-Sans.woff2') format('woff2');font-weight:200 900;font-display:swap}.company-channels{font-family:'Enterprise Mona Sans','Mona Sans',Inter,sans-serif;color:#17243f;padding:28px 32px 38px;width:100%;max-width:1400px;margin:auto;box-sizing:border-box}header{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:26px}.eyebrow{font-size:10px;letter-spacing:.12em;font-weight:650;color:#71809a;margin:0 0 9px}h1{font-size:25px;font-weight:600;letter-spacing:-.8px;line-height:1.25;margin:0 0 8px}.intro{font-size:12px;color:#71809a;margin:0;line-height:1.7}button,input,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:default}.primary,.secondary{border-radius:8px;padding:10px 14px;font-size:12px;font-weight:550;display:inline-flex;align-items:center;justify-content:center;gap:8px;white-space:nowrap}.primary{border:1px solid #3466f6;color:white;background:#3466f6}.primary:hover:not(:disabled){background:#2857df}.primary svg{width:16px;height:16px}.secondary{border:1px solid #e6ebf4;color:#17243f;background:white}.secondary:hover:not(:disabled){background:#f6f8fc}.compact{font-size:11px;padding:7px 10px}.text-button{border:0;background:none;padding:0;color:#3466f6;font-size:11px}.layout{display:grid;grid-template-columns:1fr;gap:22px;align-items:start}.layout.editing{grid-template-columns:minmax(0,1fr) minmax(340px,400px)}.channel-list{border:1px solid #e6ebf4;border-radius:12px;overflow:hidden;background:white;min-width:0}.list-toolbar{display:flex;align-items:center;gap:15px;padding:15px 17px;border-bottom:1px solid #e6ebf4}.list-toolbar>span{font-size:10px;color:#71809a;white-space:nowrap}.search{display:flex;align-items:center;gap:8px;flex:1;min-width:0}.search svg{width:17px;height:17px;color:#8a98ae;flex:none}.search input{border:0;background:none;outline:none;width:100%;min-width:40px;font-size:12px;color:#17243f}.search input::placeholder{color:#8997ac}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px}th{background:#f6f8fc;color:#71809a;font-size:10px;font-weight:500;padding:11px 16px}td{padding:17px 16px;border-top:1px solid #eef1f6;vertical-align:middle}.channel-name{display:flex;align-items:flex-start;gap:10px;min-width:160px;max-width:310px}.hash{color:#7e8faa;background:#f6f8fc;border:1px solid #e6ebf4;border-radius:8px;width:29px;height:29px;display:grid;place-items:center;font-size:18px;flex:none}.channel-name>div{min-width:0}.channel-name strong{font-size:12px;font-weight:550;overflow-wrap:anywhere}.channel-name p{font-size:10px;color:#71809a;line-height:1.6;margin:5px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.visibility{display:inline-flex;align-items:center;gap:4px;border:1px solid #e6ebf4;background:#f6f8fc;color:#71809a;border-radius:5px;font-size:9px;padding:4px 7px;white-space:nowrap}.visibility.private{color:#65718a;background:#fff}.visibility svg{width:13px;height:13px}.counts{white-space:nowrap;font-size:10px;color:#71809a}.counts span,.counts small{display:block}.counts small{font-size:9px;margin-top:4px;color:#98a3b5}.row-actions{text-align:right;white-space:nowrap}.row-actions .open{display:block;margin:9px 0 0 auto;font-size:10px}.selected{background:#f9fbff}.paging{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 17px;border-top:1px solid #e6ebf4;font-size:10px;color:#71809a}.table-empty{text-align:center;color:#71809a;font-size:12px;padding:40px 20px}.editor{border:1px solid #e6ebf4;border-radius:12px;background:white;min-width:0;padding:21px}.editor-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;margin-bottom:23px}.editor-heading .eyebrow{font-size:9px;margin-bottom:7px}h2{font-size:18px;font-weight:550;letter-spacing:-.35px;margin:0}.icon-button{background:none;border:0;color:#8a98ad;font-size:23px;line-height:1;padding:0}.editor form>label{display:block;font-size:11px;font-weight:550;margin:18px 0 8px}.editor form>label>span{font-weight:400;color:#8b98ac;font-size:10px;margin-left:4px}.name-field{display:flex;align-items:center;gap:9px;border:1px solid #e6ebf4;border-radius:8px;padding:0 11px}.name-field>span{color:#91a0b5;font-size:16px}.name-field input{width:100%;min-width:0;outline:none;border:0;color:#17243f;padding:10px 0;font-size:12px;background:none}textarea{box-sizing:border-box;width:100%;resize:vertical;border:1px solid #e6ebf4;border-radius:8px;padding:10px 11px;color:#17243f;font-size:12px;line-height:1.7;outline:none;background:white}textarea::placeholder{color:#9aa6b8}.visibility-choices{padding:0;border:0;margin:21px 0 0}.visibility-choices legend,.member-picker legend{font-size:11px;font-weight:550;margin-bottom:10px;padding:0}.visibility-choices>label{display:flex;gap:10px;padding:12px;border:1px solid #e6ebf4;border-radius:8px;margin-bottom:8px;cursor:pointer}.visibility-choices>label.chosen{border-color:#a7bffa;background:#f6f9ff}.visibility-choices input{accent-color:#3466f6;flex:none;margin:3px 0 0}.visibility-choices strong{display:block;font-size:11px;font-weight:500}.visibility-choices small{display:block;color:#71809a;font-size:10px;line-height:1.6;margin-top:4px}.member-picker{margin:20px 0 0;padding:0;border:0;max-height:210px;overflow:auto}.member-picker legend span{font-size:9px;font-weight:400;color:#8b98ac;margin-left:7px}.member-picker>label{display:flex;align-items:center;gap:9px;padding:8px 0;font-size:11px;cursor:pointer}.member-picker input{accent-color:#3466f6;margin:0;flex:none}.initial{display:grid;place-items:center;border-radius:50%;background:#f0f3f8;color:#7c8fae;width:25px;height:25px;font-size:10px;flex:none}.initial.agent{border-radius:8px;background:#eef3ff;color:#6887c4}.member-picker small{display:block;font-size:9px;color:#8c9bb2;margin-top:3px}.hint,.muted{color:#8a98ad;font-size:10px;line-height:1.7;margin:10px 0 0}.info{background:#f6f8fc;border:1px solid #e6ebf4;color:#71809a;padding:11px 12px;border-radius:8px;font-size:10px;line-height:1.7;margin:14px 0}.restricted{background:#fffaf1;border-color:#f0e7d6;color:#927a54}.safety{border-top:1px solid #eef1f6;padding-top:13px}footer{display:flex;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid #e6ebf4;padding-top:18px;margin-top:21px}footer button{font-size:11px;padding:9px 12px}footer .primary{margin-left:auto}.alert,.notice{font-size:12px;line-height:1.7;padding:12px 15px;border-radius:8px;margin:0 0 18px}.alert{background:#fff5f5;border:1px solid #f2d9db;color:#a14d55}.notice{background:#f1f8f3;border:1px solid #dbece0;color:#547e64}.alert.small{font-size:10px;margin-top:13px;padding:10px}.empty{text-align:center;padding:45px 20px;border:1px solid #e6ebf4;border-radius:12px;color:#71809a}.empty-icon{width:45px;height:45px;display:grid;place-items:center;margin:0 auto 18px;border-radius:12px;background:#f6f8fc;font-size:24px;color:#8498b6}.empty h2{color:#17243f;font-size:17px}.empty p{font-size:12px;line-height:1.7;margin:12px auto 20px;max-width:400px}.editor-loading{font-size:12px;color:#71809a;padding:25px 0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid #7e9fff;outline-offset:3px}h2:focus{outline:none}@media(max-width:1100px){.layout.editing{grid-template-columns:1fr}.editor{max-width:680px;width:100%;box-sizing:border-box}.channel-name{max-width:400px}}@media(max-width:650px){.company-channels{padding:21px 16px}header{align-items:flex-start;gap:15px}.intro{max-width:245px;font-size:11px}h1{font-size:23px}.primary{font-size:11px;padding:9px 11px}.list-toolbar{padding:13px 12px;gap:10px}.list-toolbar>span{display:none}th,td{padding:12px 10px}.counts{display:none}.channel-name{min-width:140px;max-width:230px}.editor{padding:18px}.paging{padding:12px}.row-actions .compact{padding:6px 8px;font-size:10px}}
</style>


